%[text] # Visually inspect buildElevationProfileFromRoadGradeProfileData
% HorizontalDistance = [ 0 50 100, 200 250 300, 400 450 500 ];
% RoadGradePercent = [ 0 0 0, 1 1 1, 0 0 0 ];

HorizontalDistance = [ 0 50 100, 200 250 300, 400 450 500, 600 650 700, 800 850 900 ];
RoadGradePercent = [ 0 0 0, 5 5 5, 0 0 0, -2 -2 -2, 0 0 0 ];
%[text] 
InterpolationMethod = "smooth";
LeftElevation = 0;
InterpolationInterval = 0.05;

% !inspection-target
refined_data = buildElevationProfileFromRoadGradeProfileData( ...
  HorizontalDistance, RoadGradePercent, InterpolationMethod, LeftElevation, InterpolationInterval);

plotElevationAndRoadGradeProfiles( ... %[output:group:9510479d] %[output:11658c2e]
  DataSource = "direct", ... %[output:11658c2e]
  HorizontalDistance = refined_data.x, ... %[output:11658c2e]
  GradePercent = refined_data.grade, ... %[output:11658c2e]
  Elevation = refined_data.z ) %[output:group:9510479d] %[output:11658c2e]
